// ServerInterface represents all server handlers.
type ServerInterface interface {
	// The whole contact event log, newest first
	// (GET /activity)
	ListActivity(w http.ResponseWriter, r *http.Request, params ListActivityParams)
	// Generation history
	// (GET /ai/generations)
	ListAiGenerations(w http.ResponseWriter, r *http.Request, params ListAiGenerationsParams)
	// Build the prompt for a brief, and run it when the provider can
	// (POST /ai/generations)
	CreateAiGeneration(w http.ResponseWriter, r *http.Request)
	// One generation with its brief, prompt and parsed output
	// (GET /ai/generations/{id})
	GetAiGeneration(w http.ResponseWriter, r *http.Request, id IdPath)
	// Turn chosen parts of a parsed generation into components and variants
	// (POST /ai/generations/{id}/import)
	ImportAiGeneration(w http.ResponseWriter, r *http.Request, id IdPath)
	// Validate and store the JSON the operator pasted back from ChatGPT
	// (POST /ai/generations/{id}/parse)
	ParseAiGeneration(w http.ResponseWriter, r *http.Request, id IdPath)
	// Which AI provider is configured and whether it generates or is pasted into
	// (GET /ai/provider)
	GetAiProvider(w http.ResponseWriter, r *http.Request)
	// Master business list
	// (GET /businesses)
	ListBusinesses(w http.ResponseWriter, r *http.Request, params ListBusinessesParams)
	// Suppress or unsuppress many businesses at once
	// (POST /businesses/bulk)
	BulkUpdateBusinesses(w http.ResponseWriter, r *http.Request)
	// Stream a filtered business set as CSV
	// (POST /businesses/export)
	ExportBusinesses(w http.ResponseWriter, r *http.Request)
	// Re-crawl selected or filtered businesses for emails and/or social profiles
	// (POST /businesses/recrawl)
	RecrawlBusinesses(w http.ResponseWriter, r *http.Request)
	// Business detail with every known email
	// (GET /businesses/{id})
	GetBusiness(w http.ResponseWriter, r *http.Request, id IdPath)
	// Update suppression flag or notes
	// (PATCH /businesses/{id})
	UpdateBusiness(w http.ResponseWriter, r *http.Request, id IdPath)
	// One campaign's metrics beside Instantly's, with the disagreements called out
	// (GET /campaign-analytics/campaigns/{id})
	GetCampaignAnalytics(w http.ResponseWriter, r *http.Request, id IdPath, params GetCampaignAnalyticsParams)
	// How each variant of this campaign performed
	// (GET /campaign-analytics/campaigns/{id}/variants)
	GetCampaignVariantAnalytics(w http.ResponseWriter, r *http.Request, id IdPath)
	// How each component performed across the sends that carried it
	// (GET /campaign-analytics/components)
	GetComponentAnalytics(w http.ResponseWriter, r *http.Request, params GetComponentAnalyticsParams)
	// The cold → subscriber funnel, optionally for one campaign
	// (GET /campaign-analytics/funnel)
	GetFunnelAnalytics(w http.ResponseWriter, r *http.Request, params GetFunnelAnalyticsParams)
	// Campaign counts, the funnel and the overall metrics for the whole area
	// (GET /campaign-analytics/overview)
	GetCampaignOverview(w http.ResponseWriter, r *http.Request)
	// Per-mailbox deliverability, ours beside Instantly's
	// (GET /campaign-analytics/sending-accounts)
	GetAccountAnalytics(w http.ResponseWriter, r *http.Request)
	// Campaign list with the counters the dashboard shows
	// (GET /campaigns)
	ListCampaigns(w http.ResponseWriter, r *http.Request, params ListCampaignsParams)
	// Create a draft campaign
	// (POST /campaigns)
	CreateCampaign(w http.ResponseWriter, r *http.Request)
	// Archive a campaign
	// (DELETE /campaigns/{id})
	ArchiveCampaign(w http.ResponseWriter, r *http.Request, id IdPath)
	// Campaign with its sending accounts, variants, counts and launch checklist
	// (GET /campaigns/{id})
	GetCampaign(w http.ResponseWriter, r *http.Request, id IdPath)
	// Update a campaign's name, brief, schedule, settings or steps
	// (PATCH /campaigns/{id})
	UpdateCampaign(w http.ResponseWriter, r *http.Request, id IdPath)
	// This campaign's slice of the contact event log
	// (GET /campaigns/{id}/activity)
	ListCampaignActivity(w http.ResponseWriter, r *http.Request, id IdPath, params ListCampaignActivityParams)
	// What still stands between this campaign and a launch
	// (GET /campaigns/{id}/checklist)
	GetCampaignChecklist(w http.ResponseWriter, r *http.Request, id IdPath)
	// Create the campaign at Instantly and start pushing its leads
	// (POST /campaigns/{id}/launch)
	LaunchCampaign(w http.ResponseWriter, r *http.Request, id IdPath)
	// The campaign's leads joined with their contacts
	// (GET /campaigns/{id}/leads)
	ListCampaignLeads(w http.ResponseWriter, r *http.Request, id IdPath, params ListCampaignLeadsParams)
	// Turn scraped businesses into contacts and attach them as leads
	// (POST /campaigns/{id}/leads/import)
	ImportCampaignLeads(w http.ResponseWriter, r *http.Request, id IdPath)
	// What the same import would do, without doing it
	// (POST /campaigns/{id}/leads/import/estimate)
	EstimateCampaignLeadImport(w http.ResponseWriter, r *http.Request, id IdPath)
	// Remove a lead from the campaign
	// (DELETE /campaigns/{id}/leads/{leadId})
	DeleteCampaignLead(w http.ResponseWriter, r *http.Request, id IdPath, leadId LeadIdPath)
	// One lead with its contact, variant assignments, sends and events
	// (GET /campaigns/{id}/leads/{leadId})
	GetCampaignLead(w http.ResponseWriter, r *http.Request, id IdPath, leadId LeadIdPath)
	// Pause sending at Instantly
	// (POST /campaigns/{id}/pause)
	PauseCampaign(w http.ResponseWriter, r *http.Request, id IdPath)
	// Resume a paused campaign
	// (POST /campaigns/{id}/resume)
	ResumeCampaign(w http.ResponseWriter, r *http.Request, id IdPath)
	// Replace the set of mailboxes this campaign sends from
	// (PUT /campaigns/{id}/sending-accounts)
	SetCampaignSendingAccounts(w http.ResponseWriter, r *http.Request, id IdPath)
	// Queue a reconciliation of this campaign against Instantly
	// (POST /campaigns/{id}/sync)
	SyncCampaign(w http.ResponseWriter, r *http.Request, id IdPath)
	// The variants attached to this campaign with their per-step weights
	// (GET /campaigns/{id}/variants)
	ListCampaignVariants(w http.ResponseWriter, r *http.Request, id IdPath)
	// Replace the variant mix, which bumps the campaign's weights version
	// (PUT /campaigns/{id}/variants)
	SetCampaignVariants(w http.ResponseWriter, r *http.Request, id IdPath)
	// The contact master list
	// (GET /contacts)
	ListContacts(w http.ResponseWriter, r *http.Request, params ListContactsParams)
	// One contact with its campaigns, consents, suppressions and subscriptions
	// (GET /contacts/{id})
	GetContact(w http.ResponseWriter, r *http.Request, id IdPath)
	// Update the contact's profile fields
	// (PATCH /contacts/{id})
	UpdateContact(w http.ResponseWriter, r *http.Request, id IdPath)
	// Capture the permission that lets this contact be pushed to the newsletter
	// (POST /contacts/{id}/consents)
	CreateContactConsent(w http.ResponseWriter, r *http.Request, id IdPath)
	// Withdraw a consent record
	// (POST /contacts/{id}/consents/{consentId}/revoke)
	RevokeContactConsent(w http.ResponseWriter, r *http.Request, id IdPath, consentId ConsentIdPath)
	// Record that newsletter permission was asked for
	// (POST /contacts/{id}/permission-request)
	RequestContactPermission(w http.ResponseWriter, r *http.Request, id IdPath)
	// Stop contacting this person
	// (POST /contacts/{id}/suppress)
	SuppressContact(w http.ResponseWriter, r *http.Request, id IdPath)
	// Lift a reversible suppression
	// (POST /contacts/{id}/suppressions/{suppressionId}/lift)
	LiftContactSuppression(w http.ResponseWriter, r *http.Request, id IdPath, suppressionId SuppressionIdPath)
	// Everything that has happened to this contact, newest first
	// (GET /contacts/{id}/timeline)
	GetContactTimeline(w http.ResponseWriter, r *http.Request, id IdPath, params GetContactTimelineParams)
	// The reusable building blocks an email is assembled from
	// (GET /content/components)
	ListEmailComponents(w http.ResponseWriter, r *http.Request, params ListEmailComponentsParams)
	// Write a new component
	// (POST /content/components)
	CreateEmailComponent(w http.ResponseWriter, r *http.Request)
	// One component
	// (GET /content/components/{id})
	GetEmailComponent(w http.ResponseWriter, r *http.Request, id IdPath)
	// Edit a component's text, name, tags or language
	// (PATCH /content/components/{id})
	UpdateEmailComponent(w http.ResponseWriter, r *http.Request, id IdPath)
	// Move a component through the review flow
	// (POST /content/components/{id}/status)
	SetEmailComponentStatus(w http.ResponseWriter, r *http.Request, id IdPath)
	// Which variants, campaigns and locked assignments depend on this component
	// (GET /content/components/{id}/usage)
	GetEmailComponentUsage(w http.ResponseWriter, r *http.Request, id IdPath)
	// Render an ad-hoc set of component slots without saving a variant
	// (POST /content/preview)
	PreviewEmailComponents(w http.ResponseWriter, r *http.Request)
	// The assembled email variants
	// (GET /content/variants)
	ListEmailVariants(w http.ResponseWriter, r *http.Request, params ListEmailVariantsParams)
	// Assemble components into a variant
	// (POST /content/variants)
	CreateEmailVariant(w http.ResponseWriter, r *http.Request)
	// One variant with its slots and the campaigns using it
	// (GET /content/variants/{id})
	GetEmailVariant(w http.ResponseWriter, r *http.Request, id IdPath)
	// Rename a variant, move its step or re-pick its components
	// (PATCH /content/variants/{id})
	UpdateEmailVariant(w http.ResponseWriter, r *http.Request, id IdPath)
	// Render a variant, optionally against a real contact
	// (POST /content/variants/{id}/preview)
	PreviewEmailVariant(w http.ResponseWriter, r *http.Request, id IdPath)
	// Move a variant through the review flow
	// (POST /content/variants/{id}/status)
	SetEmailVariantStatus(w http.ResponseWriter, r *http.Request, id IdPath)
	// Liveness probe with dependency checks
	// (GET /healthz)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// State of every outreach integration, its webhook and its event log
	// (GET /integrations)
	GetIntegrations(w http.ResponseWriter, r *http.Request)
	// The raw provider event log, newest first
	// (GET /integrations/events)
	ListProviderEvents(w http.ResponseWriter, r *http.Request, params ListProviderEventsParams)
	// Replay one stored provider event through the ingest pipeline
	// (POST /integrations/events/{id}/reprocess)
	ReprocessProviderEvent(w http.ResponseWriter, r *http.Request, id IdPath)
	// Validate the stored Instantly key with a single API call
	// (POST /integrations/instantly/test)
	TestInstantlyConnection(w http.ResponseWriter, r *http.Request)
	// Remove the Instantly webhook registration
	// (DELETE /integrations/instantly/webhook)
	DeleteInstantlyWebhook(w http.ResponseWriter, r *http.Request)
	// Register (or rotate) the Instantly webhook that feeds the event log
	// (POST /integrations/instantly/webhook)
	RegisterInstantlyWebhook(w http.ResponseWriter, r *http.Request)
	// Validate the stored Mailchimp key with a single API call
	// (POST /integrations/mailchimp/test)
	TestMailchimpConnection(w http.ResponseWriter, r *http.Request)
	// History of the reconciliation runs against both providers
	// (GET /integrations/sync-runs)
	ListSyncRuns(w http.ResponseWriter, r *http.Request, params ListSyncRunsParams)
	// Job history
	// (GET /jobs)
	ListJobs(w http.ResponseWriter, r *http.Request, params ListJobsParams)
	// Create and enqueue a scrape job
	// (POST /jobs)
	CreateJob(w http.ResponseWriter, r *http.Request)
	// Estimate query count and provider cost for a config
	// (POST /jobs/estimate)
	EstimateJob(w http.ResponseWriter, r *http.Request)
	// Delete a job with its queries, events and result links
	// (DELETE /jobs/{id})
	DeleteJob(w http.ResponseWriter, r *http.Request, id IdPath)
	// Job detail including stats
	// (GET /jobs/{id})
	GetJob(w http.ResponseWriter, r *http.Request, id IdPath)
	// Cooperatively cancel a queued or running job
	// (POST /jobs/{id}/cancel)
	CancelJob(w http.ResponseWriter, r *http.Request, id IdPath)
	// Server-Sent Events stream of job progress, logs and status
	// (GET /jobs/{id}/events)
	StreamJobEvents(w http.ResponseWriter, r *http.Request, id IdPath, params StreamJobEventsParams)
	// Stream this job's businesses and emails as CSV
	// (GET /jobs/{id}/export.csv)
	ExportJobCsv(w http.ResponseWriter, r *http.Request, id IdPath)
	// Re-crawl a finished job's websites without a new provider search
	// (POST /jobs/{id}/recrawl)
	RecrawlJob(w http.ResponseWriter, r *http.Request, id IdPath)
	// Clone a job's config into a new queued job
	// (POST /jobs/{id}/rerun)
	RerunJob(w http.ResponseWriter, r *http.Request, id IdPath)
	// The Mailchimp audiences known here
	// (GET /newsletter/audiences)
	ListNewsletterAudiences(w http.ResponseWriter, r *http.Request)
	// Queue a refresh of the audience list from Mailchimp
	// (POST /newsletter/audiences/sync)
	SyncNewsletterAudiences(w http.ResponseWriter, r *http.Request)
	// Set the audience's opt-in policy, default tags and default flag
	// (PATCH /newsletter/audiences/{id})
	UpdateNewsletterAudience(w http.ResponseWriter, r *http.Request, id IdPath)
	// Remove this audience's Mailchimp webhook
	// (DELETE /newsletter/audiences/{id}/webhook)
	DeleteNewsletterWebhook(w http.ResponseWriter, r *http.Request, id IdPath)
	// Register this audience's Mailchimp webhook
	// (POST /newsletter/audiences/{id}/webhook)
	RegisterNewsletterWebhook(w http.ResponseWriter, r *http.Request, id IdPath)
	// Who could be pushed to the newsletter now, and who is one step short
	// (GET /newsletter/eligibility)
	ListNewsletterEligibility(w http.ResponseWriter, r *http.Request, params ListNewsletterEligibilityParams)
	// Queue contacts for Mailchimp
	// (POST /newsletter/push)
	PushNewsletterContacts(w http.ResponseWriter, r *http.Request)
	// Subscription counts by status and the eligible → subscribed conversion
	// (GET /newsletter/stats)
	GetNewsletterStats(w http.ResponseWriter, r *http.Request)
	// Every subscription with what we asked for and what Mailchimp says
	// (GET /newsletter/subscriptions)
	ListNewsletterSubscriptions(w http.ResponseWriter, r *http.Request, params ListNewsletterSubscriptionsParams)
	// Re-queue a subscription whose push to Mailchimp failed
	// (POST /newsletter/subscriptions/{id}/retry)
	RetryNewsletterSubscription(w http.ResponseWriter, r *http.Request, id IdPath)
	// This OpenAPI document as JSON (used by the frontend codegen)
	// (GET /openapi.json)
	GetOpenapiSpec(w http.ResponseWriter, r *http.Request)
	// The mailboxes Instantly sends from, with their recent stats
	// (GET /sending-accounts)
	ListSendingAccounts(w http.ResponseWriter, r *http.Request, params ListSendingAccountsParams)
	// Queue a refresh of the account list and its daily stats from Instantly
	// (POST /sending-accounts/sync)
	SyncSendingAccounts(w http.ResponseWriter, r *http.Request)
	// One mailbox with its daily series and the campaigns it serves
	// (GET /sending-accounts/{id})
	GetSendingAccount(w http.ResponseWriter, r *http.Request, id IdPath)
	// List configured providers
	// (GET /sources)
	ListSources(w http.ResponseWriter, r *http.Request)
	// Get a single provider
	// (GET /sources/{id})
	GetSource(w http.ResponseWriter, r *http.Request, id IdPath)
	// Update provider key, cost and enabled flag
	// (PUT /sources/{id})
	UpdateSource(w http.ResponseWriter, r *http.Request, id IdPath)
	// Validate the stored API key with a single-result provider call
	// (POST /sources/{id}/test)
	TestSource(w http.ResponseWriter, r *http.Request, id IdPath)
	// Dashboard counters and per-job email chart data
	// (GET /stats/scraper)
	GetScraperStats(w http.ResponseWriter, r *http.Request)
	// Every address that has been through, or is queued for, verification
	// (GET /verification/emails)
	ListVerifications(w http.ResponseWriter, r *http.Request, params ListVerificationsParams)
	// One address with its full Pass 1 breakdown and raw provider payload
	// (GET /verification/emails/{id})
	GetVerification(w http.ResponseWriter, r *http.Request, id IdPath)
	// Rewrite every business holding the misspelled address to the suggested one
	// (POST /verification/emails/{id}/apply-typo)
	ApplyTypoSuggestion(w http.ResponseWriter, r *http.Request, id IdPath)
	// Queue the free local pass for one address
	// (POST /verification/emails/{id}/self)
	VerifyEmailSelf(w http.ResponseWriter, r *http.Request, id IdPath)
	// Queue the paid provider check for one address
	// (POST /verification/emails/{id}/third-party)
	VerifyEmailThirdParty(w http.ResponseWriter, r *http.Request, id IdPath)
	// Run history
	// (GET /verification/runs)
	ListVerificationRuns(w http.ResponseWriter, r *http.Request, params ListVerificationRunsParams)
	// Start a bulk verification run
	// (POST /verification/runs)
	CreateVerificationRun(w http.ResponseWriter, r *http.Request)
	// How many addresses a run would process, and what it would cost
	// (POST /verification/runs/estimate)
	EstimateVerificationRun(w http.ResponseWriter, r *http.Request)
	// Run progress, polled while a run is active
	// (GET /verification/runs/{id})
	GetVerificationRun(w http.ResponseWriter, r *http.Request, id IdPath)
	// Cooperatively cancel a queued or running verification run
	// (POST /verification/runs/{id}/cancel)
	CancelVerificationRun(w http.ResponseWriter, r *http.Request, id IdPath)
	// Provider weights, toggles, the paid band and live provider health
	// (GET /verification/settings)
	GetVerificationSettings(w http.ResponseWriter, r *http.Request)
	// Replace the verification settings
	// (PUT /verification/settings)
	UpdateVerificationSettings(w http.ResponseWriter, r *http.Request)
	// Tag distribution, pass coverage, credits and the current cost to verify
	// (GET /verification/stats)
	GetVerificationStats(w http.ResponseWriter, r *http.Request)
	// Instantly event delivery endpoint
	// (POST /webhooks/instantly/{token})
	ReceiveInstantlyWebhook(w http.ResponseWriter, r *http.Request, token WebhookTokenPath)
	// Mailchimp's reachability probe, which must answer 200 with no body
	// (GET /webhooks/mailchimp/{token})
	VerifyMailchimpWebhook(w http.ResponseWriter, r *http.Request, token WebhookTokenPath)
	// Mailchimp event delivery endpoint
	// (POST /webhooks/mailchimp/{token})
	ReceiveMailchimpWebhook(w http.ResponseWriter, r *http.Request, token WebhookTokenPath)
}

